        self.rectangles = rectangles
        self.colors = set([color for r in rectangles for color in r[3]])
        self.color_map = {color: i for i, color in enumerate(self.colors)}
        self.tree = [[0 for _ in range(len(self.colors))] for _ in range(4 * len(rectangles))]

