        if start == end:
            self.tree[node] = [0 for _ in range(len(self.colors))]
            return
        mid = (start + end) // 2
        self.build_tree(2 * node + 1, start, mid, index)
        self.build_tree(2 * node + 2, mid + 1, end, index)
        for i in range(mid - start + 1):
            color = self.color_map[self.rectangles[index + i][3]]
            self.tree[node][color] += self.tree[2 * node + 1][color] + self.tree[2 * node + 2][color] + 1

