        if start == end:
            self.tree[node][color] = value
            return
        mid = (start + end) // 2
        if index <= mid:
            self.update(2 * node + 1, start, mid, index, value, color)
        else:
            self.update(2 * node + 2, mid + 1, end, index, value, color)
        self.tree[node] = [self.tree[2 * node + 1][i] + self.tree[2 * node + 2][i] + (i == color) for i in range(len(self.colors))]

